// rustc -O -C target-cpu=native. Input from ramsey310_pack_frontier.py.
use std::{collections::HashMap,env,fs};
#[derive(Clone,Copy,Default)] struct B([u64;12]);
impl B{fn put(&mut self,i:usize){self.0[i/64]|=1<<(i%64)} fn sub(&mut self,b:B){for i in 0..12{self.0[i]&=!b.0[i]}} fn and(mut self,b:B)->B{for i in 0..12{self.0[i]&=b.0[i]}self} fn add(&mut self,b:B){for i in 0..12{self.0[i]|=b.0[i]}} fn count(self)->u32{self.0.iter().map(|x|x.count_ones()).sum()} fn each(self,mut f:impl FnMut(usize)){for (i,mut x) in self.0.into_iter().enumerate(){while x!=0{let j=x.trailing_zeros()as usize;x&=x-1;f(64*i+j)}}}}
fn filter(adj:&mut[B],m:B){m.each(|j|adj[j].sub(m))}
struct Data{a:Vec<u32>,s:Vec<u32>,c:Vec<u32>,inc:[B;27],miss:Vec<B>,miss6:Vec<B>,base:Vec<B>,sing:HashMap<usize,Vec<B>>,trip:Vec<B>}
impl Data{fn new(a:Vec<u32>,s:Vec<u32>,c:Vec<u32>)->Self{let n=c.len();assert_eq!(n,750);let mask=|t:u32|{let mut b=B::default();for(i,&x)in c.iter().enumerate(){if x&t==0{b.put(i)}}b};let miss:Vec<_>=c.iter().copied().map(mask).collect();let miss6=s.iter().copied().map(mask).collect();let mut inc=[B::default();27];let mut base=vec![B::default();n];for(i,&x)in c.iter().enumerate(){for v in 0..27{if x>>v&1!=0{inc[v].put(i)}}for(j,&y)in c.iter().enumerate(){if (x&y).count_ones()<=5{base[i].put(j)}}}let mut trip=vec![B::default();n*n];for i in 0..n{for j in 0..i{let mut m=B::default();miss[i].and(miss[j]).each(|t|m.add(miss[t]));trip[i*n+j]=m;trip[j*n+i]=m}}Self{a,s,c,inc,miss,miss6,base,sing:HashMap::new(),trip}}
fn single(&mut self,i:usize){if self.sing.contains_key(&i){return}let mut adj=self.base.clone();for(j,&t)in self.c.iter().enumerate(){if t&self.s[i]==0{filter(&mut adj,self.miss[j])}}self.sing.insert(i,adj);}
fn possible(&mut self,side:usize)->bool{let n=self.s.len();let(i,j)=(side/n,side%n);self.single(i);self.single(j);let u=self.s[i]|self.s[j];let mut adj:Vec<_>=self.sing[&i].iter().zip(&self.sing[&j]).map(|(&x,&y)|x.and(y)).collect();for(h,&t)in self.s.iter().enumerate(){if t&u==0{filter(&mut adj,self.miss6[h])}}let mut pool=B::default();for i in 0..self.c.len(){pool.put(i)}let mut hi=[0i8;27];let mut lo=hi;for v in 0..27{hi[v]=9-(self.a[v].count_ones()+(self.s[i]>>v&1)+(self.s[j]>>v&1))as i8;lo[v]=if u>>v&1!=0{hi[v]}else{(hi[v]-2).max(0)};if hi[v]==1{filter(&mut adj,self.inc[v])}}self.dfs(&adj,pool,7,lo,hi,&mut[0;7])}
fn dfs(&self,adj:&[B],mut p:B,k:i8,lo:[i8;27],hi:[i8;27],ids:&mut[usize;7])->bool{if k==0{return lo.iter().all(|&x|x<=0)}for v in 0..27{if hi[v]<0||lo[v]>k{return false}if hi[v]==0{p.sub(self.inc[v])}if lo[v]==k{p=p.and(self.inc[v])}}let mut sz=p.count();if sz<(k as u32){return false}let mut opt=p;for v in 0..27{if lo[v]>0{let t=p.and(self.inc[v]);let n=t.count();if n<(lo[v]as u32){return false}if n<sz{opt=t;sz=n}}}for w in 0..12{let mut x=opt.0[w];while x!=0{let b=x.trailing_zeros()as usize;x&=x-1;p.0[w]&=!(1<<b);let i=64*w+b;let mut m=p.and(adj[i]);for &j in &ids[..(7-k)as usize]{m.sub(self.trip[i*self.c.len()+j])}if m.count()+1<k as u32{continue}let mut l=lo;let mut h=hi;let mut t=self.c[i];while t!=0{let v=t.trailing_zeros()as usize;t&=t-1;l[v]-=1;h[v]-=1}ids[(7-k)as usize]=i;if self.dfs(adj,m,k-1,l,h,ids){return true}}}false}}
fn main(){let args:Vec<_>=env::args().collect();let txt=fs::read_to_string(&args[1]).unwrap();let mut it=txt.split_whitespace().map(|x|x.parse::<u32>().unwrap());let mut read=||{let n=it.next().unwrap();(0..n).map(|_|it.next().unwrap()).collect::<Vec<_>>()};let mut d=Data::new(read(),read(),read());let mut map:HashMap<usize,Vec<usize>>=HashMap::new();let mut total=0;while let Some(x)=it.next(){let y=it.next().unwrap();map.entry(x as usize).or_default().push(y as usize);map.entry(y as usize).or_default().push(x as usize);total+=1}let mut order:Vec<_>=map.keys().copied().collect();order.sort_by_key(|&i|(std::cmp::Reverse(map[&i].len()),i));let mut fails=std::collections::HashSet::new();let limit=args.get(2).map_or(usize::MAX,|s|s.parse().unwrap());let mut done=0;let mut left=total;for i in order{let gain=map[&i].iter().filter(|j|!fails.contains(*j)).count();if gain==0{continue}if done==limit{break}done+=1;if !d.possible(i){left-=gain;fails.insert(i);}else{println!("pass {} {}",d.s[i/d.s.len()],d.s[i%d.s.len()])}if done%5000==0{eprintln!("tested {done} remaining {left}")}}println!("tested {done} failed {} total {total} unresolved {left}",fails.len());}
